func main() {
	root := "."
	fset := token.NewFileSet()

	var allFiles []string
	var internalFiles []string

	filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() {
			if info != nil && info.IsDir() && (info.Name() == ".git" || info.Name() == "vendor") {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
			return nil
		}
		allFiles = append(allFiles, path)
		if strings.Contains(path, string(filepath.Separator)+"internal"+string(filepath.Separator)) {
			internalFiles = append(internalFiles, path)
		}
		return nil
	})

	// Collect declared symbols in internal/
	decls := make(map[string]symbol) // key: file:name:recv
	for _, path := range internalFiles {
		f, err := parser.ParseFile(fset, path, nil, 0)
		if err != nil {
			continue
		}
		pkg := f.Name.Name
		for _, decl := range f.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok {
				continue
			}
			name := fn.Name.Name
			recv := ""
			if fn.Recv != nil && len(fn.Recv.List) > 0 {
				recv = exprString(fn.Recv.List[0].Type)
			}
			key := fmt.Sprintf("%s:%s:%s", path, name, recv)
			decls[key] = symbol{name: name, file: path, pkg: pkg, recvType: recv}
		}
	}

	// Count call sites across all files
	callCounts := make(map[string]int)

	for _, path := range allFiles {
		f, err := parser.ParseFile(fset, path, nil, 0)
		if err != nil {
			continue
		}
		ast.Inspect(f, func(n ast.Node) bool {
			call, ok := n.(*ast.CallExpr)
			if !ok {
				return true
			}
			switch fun := call.Fun.(type) {
			case *ast.Ident:
				name := fun.Name
				for key, sym := range decls {
					if sym.name == name && sym.recvType == "" {
						callCounts[key]++
					}
				}
			case *ast.SelectorExpr:
				name := fun.Sel.Name
				for key, sym := range decls {
					if sym.name == name && sym.recvType == "" {
						callCounts[key]++
					}
				}
			}
			return true
		})
	}

	type result struct {
		sym   symbol
		count int
	}
	var results []result
	for key, sym := range decls {
		results = append(results, result{sym: sym, count: callCounts[key]})
	}
	sort.Slice(results, func(i, j int) bool {
		return results[i].count > results[j].count
	})

	fmt.Println("TOP 40 internal symbols by fan-in (package-level func calls only):")
	for i, r := range results {
		if i >= 40 {
			break
		}
		recv := ""
		if r.sym.recvType != "" {
			recv = " (" + r.sym.recvType + ")"
		}
		fmt.Printf("%4d  %s%s  %s\n", r.count, r.sym.name, recv, r.sym.file)
	}
}

func exprString(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		return "*" + exprString(t.X)
	case *ast.SelectorExpr:
		return exprString(t.X) + "." + t.Sel.Name
	default:
		return fmt.Sprintf("%T", e)
	}
}
