perl - << 'PERLEOF'
use strict;
use warnings;
use File::Find;

my @all_files;
my @internal_files;

find({
    wanted => sub {
        return unless -f $_;
        return unless /\.go$/;
        return if /_test\.go$/;
        my $p = $File::Find::name;
        return if $p =~ m{/(?:\.git|vendor)/};
        push @all_files, $p;
        push @internal_files, $p if $p =~ m{/internal/};
    },
    no_chdir => 1,
}, '/bench/repo');

sub read_file {
    my ($path) = @_;
    open my $fh, '<', $path or return '';
    local $/;
    my $content = <$fh>;
    close $fh;
    return $content // '';
}

my %decls;

for my $path (@internal_files) {
    my $content = read_file($path);
    my ($pkg) = $content =~ /^package\s+(\w+)/m;
    $pkg //= 'unknown';

    while ($content =~ /^func\s+(?:(\([^)]*\))\s+)?(\w+)\s*\(/mg) {
        my ($recv, $name) = ($1 // '', $2);
        my $recv_type = '';
        if ($recv ne '') {
            if ($recv =~ /\*?(\w+)\s*$/) {
                $recv_type = $1;
            }
        }
        my $key = "$path\t$name\t$recv_type";
        $decls{$key} = {
            name => $name,
            file => $path,
            recv => $recv_type,
            pkg  => $pkg,
            is_method => ($recv ne '') ? 1 : 0,
        };
    }
}

my %call_counts;
for my $key (keys %decls) {
    $call_counts{$key} = 0;
}

for my $path (@all_files) {
    my $content = read_file($path);
    $content =~ s{//[^\n]*}{}g;
    $content =~ s{/\*.*?\*/}{}gs;

    for my $key (keys %decls) {
        my $sym = $decls{$key};
        my $name = $sym->{name};
        my $count = 0;

        if ($sym->{is_method}) {
            while ($content =~ /\.\Q$name\E\s*\(/g) {
                $count++;
            }
        } else {
            while ($content =~ /(?<![.\w])\Q$name\E\s*\(/g) {
                $count++;
            }
        }
        $call_counts{$key} += $count;
    }
}

for my $key (keys %decls) {
    my $sym = $decls{$key};
    my $content = read_file($sym->{file});
    my $name = $sym->{name};
    my $defs = 0;
    if ($sym->{is_method}) {
        while ($content =~ /^func\s+\([^)]*\)\s+\Q$name\E\s*\(/mg) {
            $defs++;
        }
    } else {
        while ($content =~ /^func\s+\Q$name\E\s*\(/mg) {
            $defs++;
        }
    }
    $call_counts{$key} -= $defs;
    $call_counts{$key} = 0 if $call_counts{$key} < 0;
}

my @sorted = sort { $call_counts{$b} <=> $call_counts{$a} } keys %decls;

print "TOP 50 internal symbols by fan-in:\n";
for my $i (0 .. 49) {
    last if $i >= @sorted;
    my $key = $sorted[$i];
    my $sym = $decls{$key};
    my $recv = $sym->{recv} ? " ($sym->{recv})" : '';
    printf "%4d  %s%s  %s\n", $call_counts{$key}, $sym->{name}, $recv, $sym->{file};
}
PERLEOF

